package com.ethk3.novaonepro.strategyv2;
import org.junit.Test;import static org.junit.Assert.*;
public class RepairDirectedResearchR30Test {
 @Test public void measuredChildCannotBeSubstitutedAndParentNeverChanges(){PolicySpecR27 p=RepairPairedResearchR30Test.parent();String original=p.fullJson();ResearchContractR30R1 c=new ResearchContractR30R1(StatsR27.sha256("data"),p.policyHash(),"ABI",RepairPairedResearchR30Test.SOURCE,StatsR27.sha256("input"),ResearchContractR30R1.Role.SELECT,1000,1255,0,1);ResearchGainR30R1 g=new ResearchGainR30R1(1000,1255,64,4,200);for(long t=1000;t<=1255;t++)g.add(t,.2,.3);ResearchAdviceR30R1 a=ResearchAdviceR30R1.component(c,"root/0",g.estimate(),1256,1);assertEquals(ResearchAdviceR30R1.Action.PRUNE_COMPONENT,a.action);PolicySpecR27 child=DirectedResearchPolicyR30R1.withoutChild(p,"root/0",1);assertEquals(child.policyHash(),DirectedResearchPolicyR30R1.materialize(a,c,p,child.fullJson(),child.policyHash(),1,1256,1).policyHash());PolicySpecR27 wrong=DirectedResearchPolicyR30R1.withoutChild(p,"root/1",1);try{DirectedResearchPolicyR30R1.materialize(a,c,p,wrong.fullJson(),wrong.policyHash(),1,1256,1);fail();}catch(IllegalStateException expected){}assertEquals(original,p.fullJson());assertTrue(BirthGateR27.candidateContract(child).ok);assertTrue(new BirthGateR27(RepairPairedResearchR30Test.context().cache,1000).checkCandidate(child).ok);}
 @Test public void crossBuildOrUnknownAbiCannotResumeAPendingResearchAdmission(){java.util.Map<String,Object> summary=new java.util.LinkedHashMap<>();summary.put("sourceContract",java.util.Collections.singletonMap("abi",FrozenConfirmationR30.currentSemantics()));String current=com.ethk3.novaonepro.BuildConfig.SOURCE_COMMIT_R26;assertTrue(ResearchStoreR30R1.currentSource(current,JsonR27.write(summary)));assertFalse(ResearchStoreR30R1.currentSource("0000000000000000000000000000000000000000",JsonR27.write(summary)));assertFalse(ResearchStoreR30R1.currentSource(current,"{}"));}
}
